-- Prototype catalog: the fictional games from src/data/games.ts.
-- GENERATED by scripts/generate-catalog-seed.mts — do not edit by hand.
-- Phase 3 replaces this with a licensed catalog provider sync.

insert into public.games (id, slug, title, release_date, summary, description, developer, publisher, platforms, genres, provider, provider_id)
values
  ('00000000-0000-4000-8000-000000000001', 'lanternfall', 'Lanternfall', '2026-10-30'::date, 'Carry the last lantern through a city where the night has weight.',
   'Lanternfall is a quiet action-adventure about a courier carrying the last working lantern through a drowned city. Light is a resource, a weapon and a way to talk to the people hiding in the dark. Every district you illuminate stays lit — and changes how the city sees you.', 'Small Hours Studio', 'Driftwood Interactive', array['PC', 'PlayStation 5', 'Xbox Series X|S']::text[], array['Action', 'Adventure']::text[], 'mock', '1000'),
  ('00000000-0000-4000-8000-000000000002', 'salt-and-circuit', 'Salt & Circuit', '2026-10-16'::date, 'Repair a seaside robot town one stubborn machine at a time.',
   'A cozy repair sim set on a salt-crusted coast. Rewire lighthouses, coax old fishing drones back to life and learn why the town''s machines stopped trusting people. No timers, no fail states — just tools, tides and a lot of tea.', 'Tidepool Games', 'Tidepool Games', array['PC', 'Nintendo Switch 2', 'macOS']::text[], array['Simulation', 'Cozy']::text[], 'mock', '1001'),
  ('00000000-0000-4000-8000-000000000003', 'hollow-meridian', 'Hollow Meridian', '2026-10-02'::date, 'A survival horror descent into an observatory that shouldn''t exist.',
   'You arrive at Meridian Observatory to collect your sister''s research. The building is larger on the inside every time you look away. Hollow Meridian is a slow-burn survival horror game about memory, measurement and the things that hide between stars.', 'Ninth Bell', 'Greyhouse', array['PC', 'PlayStation 5']::text[], array['Horror', 'Survival']::text[], 'mock', '1002'),
  ('00000000-0000-4000-8000-000000000004', 'kitesong', 'Kitesong', '2026-09-18'::date, 'Glide between floating islands and stitch the sky back together.',
   'Kitesong is an open-air exploration game played on the wind. Build your kite from what you find, chase thermals across a broken archipelago, and play songs that pull islands back into place. Optional co-op lets a friend fly alongside you.', 'Paper Lantern Co.', 'Paper Lantern Co.', array['PC', 'Nintendo Switch 2', 'PlayStation 5', 'Xbox Series X|S']::text[], array['Exploration', 'Indie']::text[], 'mock', '1003'),
  ('00000000-0000-4000-8000-000000000005', 'iron-tenants', 'Iron Tenants', '2026-08-28'::date, 'Run a crumbling apartment block for mechs between shifts.',
   'Part management sim, part tactics game. Your tenants are retired war machines trying to live ordinary lives. Fix the plumbing, settle disputes and — when the developers come to evict everyone — defend the building one floor at a time.', 'Concrete Garden', 'Halfmoon Publishing', array['PC']::text[], array['Strategy', 'Simulation']::text[], 'mock', '1004'),
  ('00000000-0000-4000-8000-000000000006', 'velvet-static', 'Velvet Static', '2026-08-07'::date, 'A neo-noir detective story told through a late-night radio show.',
   'You host a call-in radio show in a city that never quite sleeps. Callers bring confessions, rumors and lies. Piece together a disappearance by choosing who stays on air — and who gets cut off. A narrative adventure with fully voiced callers.', 'Afterglow Narrative', 'Driftwood Interactive', array['PC', 'PlayStation 5', 'Xbox Series X|S', 'macOS']::text[], array['Narrative', 'Mystery']::text[], 'mock', '1005'),
  ('00000000-0000-4000-8000-000000000007', 'rootbound', 'Rootbound', '2026-07-10'::date, 'A roguelite where you grow your deck like a garden.',
   'In Rootbound, cards are seeds. Plant them, wait, prune and harvest. Each run is a season in a strange forest whose creatures remember how you treated them last time. Deep synergies, short runs, and a soundtrack of field recordings.', 'Mossline', 'Mossline', array['PC', 'Nintendo Switch', 'Nintendo Switch 2', 'iOS', 'Android']::text[], array['Roguelite', 'Card Game', 'Indie']::text[], 'mock', '1006'),
  ('00000000-0000-4000-8000-000000000008', 'the-long-quiet', 'The Long Quiet', '2026-06-12'::date, 'Two strangers. One rail line. A thousand kilometres of snow.',
   'A story-driven road trip on rails. Keep an old train running across a frozen continent while getting to know the only other passenger. Conversations are shaped by what you choose to talk about — and what you choose to leave unsaid.', 'Northwind Collective', 'Greyhouse', array['PC', 'PlayStation 5', 'Xbox Series X|S']::text[], array['Narrative', 'Adventure']::text[], 'mock', '1007'),
  ('00000000-0000-4000-8000-000000000009', 'pixel-pilgrims', 'Pixel Pilgrims', '2026-05-01'::date, 'A four-player couch co-op journey across a hand-drawn world.',
   'Pixel Pilgrims is a cooperative platformer built for the couch. Up to four players share one bundle of supplies on a pilgrimage to the edge of the map. Help each other, argue about routes, and laugh when someone falls off a cliff — again.', 'Bright Bench', 'Halfmoon Publishing', array['Nintendo Switch', 'Nintendo Switch 2', 'PC']::text[], array['Platformer', 'Co-op', 'Multiplayer']::text[], 'mock', '1008'),
  ('00000000-0000-4000-8000-000000000010', 'drift-protocol', 'Drift Protocol', '2026-03-20'::date, 'Arcade racing through a city that rebuilds itself every lap.',
   'An anti-gravity racer where the track is procedurally rewired in real time. Master the drift, ride the shortcuts that only exist for a second, and climb the online leagues. Supports split-screen and cross-play.', 'Overclock Studios', 'Overclock Studios', array['PC', 'PlayStation 5', 'Xbox Series X|S']::text[], array['Racing', 'Multiplayer']::text[], 'mock', '1009'),
  ('00000000-0000-4000-8000-000000000011', 'ember-and-oath', 'Ember & Oath', '2025-11-14'::date, 'A sprawling fantasy RPG where every promise has a cost.',
   'Ember & Oath is a party-based RPG about the oaths that bind a kingdom together. Swear them, keep them, or break them — and watch the world remember. Over sixty hours of story with real consequences and a tactical, pausable combat system.', 'Highcrest', 'Greyhouse', array['PC', 'PlayStation 5', 'Xbox Series X|S']::text[], array['RPG', 'Fantasy']::text[], 'mock', '1010'),
  ('00000000-0000-4000-8000-000000000012', 'glasshouse', 'Glasshouse', '2025-09-05'::date, 'A puzzle game about light, reflection and an empty greenhouse.',
   'Rotate panes, split beams and bring an abandoned greenhouse back to life. Glasshouse has no text and no timer — only around 120 handcrafted puzzles and a story told through the plants that bloom as you solve them.', 'Prism Pocket', 'Prism Pocket', array['PC', 'macOS', 'iOS', 'Android', 'Nintendo Switch']::text[], array['Puzzle', 'Indie']::text[], 'mock', '1011'),
  ('00000000-0000-4000-8000-000000000013', 'starfold-tactics', 'Starfold Tactics', '2025-06-27'::date, 'Turn-based squad tactics aboard a fleet folding through space.',
   'Command a crew aboard a ship that folds space to travel. Each jump scrambles the map — and sometimes your crew. Starfold Tactics blends grid-based combat with a branching campaign and permanent consequences.', 'Vector Nine', 'Halfmoon Publishing', array['PC', 'PlayStation 5']::text[], array['Strategy', 'Sci-Fi']::text[], 'mock', '1012'),
  ('00000000-0000-4000-8000-000000000014', 'backyard-legends', 'Backyard Legends', '2024-08-09'::date, 'Summer holidays, a bike, and a neighbourhood full of secrets.',
   'Relive the endless summer of being eleven. Ride your bike, trade cards, build a fort and uncover the legend of the house at the end of the street. A nostalgic adventure for anyone who remembers when one afternoon felt like forever.', 'Lemonade Games', 'Lemonade Games', array['PC', 'Nintendo Switch', 'PlayStation 5']::text[], array['Adventure', 'Indie']::text[], 'mock', '1013'),
  ('00000000-0000-4000-8000-000000000015', 'deepwater-signal', 'Deepwater Signal', '2024-03-15'::date, 'Answer a distress call from the bottom of the ocean.',
   'Alone in a research submarine, you follow a signal into the deepest trench on Earth. Deepwater Signal is a tense, atmospheric horror game where your sonar is your only sense and silence is your only defense.', 'Ninth Bell', 'Greyhouse', array['PC', 'PlayStation 5', 'Xbox Series X|S']::text[], array['Horror', 'Exploration']::text[], 'mock', '1014'),
  ('00000000-0000-4000-8000-000000000016', 'crown-of-nine-rivers', 'Crown of Nine Rivers', '2023-10-20'::date, 'An action RPG across a river kingdom on the brink of war.',
   'Nine rivers, nine rulers, one crown. Fight, negotiate and sail your way across a vast kingdom in this action RPG with fluid combat and a living political system.', 'Highcrest', 'Greyhouse', array['PC', 'PlayStation 5', 'Xbox Series X|S']::text[], array['RPG', 'Action']::text[], 'mock', '1015'),
  ('00000000-0000-4000-8000-000000000017', 'tiny-orbit', 'Tiny Orbit', '2022-05-12'::date, 'Build a solar system small enough to fit in your pocket.',
   'A relaxing sandbox about gravity. Place planets, nudge moons and watch tiny civilizations rise on the worlds you balance. Tiny Orbit is endlessly replayable and surprisingly emotional.', 'Prism Pocket', 'Prism Pocket', array['PC', 'macOS', 'iOS', 'Android']::text[], array['Simulation', 'Sandbox', 'Indie']::text[], 'mock', '1016'),
  ('00000000-0000-4000-8000-000000000018', 'last-arcade-on-earth', 'Last Arcade on Earth', '2021-11-03'::date, 'Keep the world''s final arcade open, one high score at a time.',
   'Part management game, part collection of original micro-arcade games. Repair cabinets, welcome regulars and keep the lights on in the last arcade on Earth. Each cabinet is a fully playable mini-game.', 'Bright Bench', 'Bright Bench', array['PC', 'Nintendo Switch', 'PlayStation 5']::text[], array['Simulation', 'Arcade']::text[], 'mock', '1017'),
  ('00000000-0000-4000-8000-000000000019', 'harbor-hearts', 'Harbor Hearts', '2020-07-24'::date, 'Run a tiny ferry and connect the lives of an island town.',
   'Ferry passengers between islands, learn their stories and help them find their way. Harbor Hearts is a short, tender narrative game that many players finish in a single evening — and remember for years.', 'Tidepool Games', 'Tidepool Games', array['PC', 'Nintendo Switch', 'iOS', 'Android']::text[], array['Narrative', 'Cozy', 'Indie']::text[], 'mock', '1018'),
  ('00000000-0000-4000-8000-000000000020', 'afterlight-protocol', 'Afterlight Protocol', '2026-12-04'::date, 'A stealth thriller set during the last night of a dying satellite city.',
   'Infiltrate an orbital city on the night its lights go out for good. Afterlight Protocol is a systemic stealth game with multiple routes, non-lethal options and a city that reacts to every alarm.', 'Overclock Studios', 'Driftwood Interactive', array['PC', 'PlayStation 5', 'Xbox Series X|S']::text[], array['Stealth', 'Action']::text[], 'mock', '1019'),
  ('00000000-0000-4000-8000-000000000021', 'moonmilk-farm', 'Moonmilk Farm', '2027-02-19'::date, 'Farm under a moon that changes what your crops become.',
   'A farming life sim where each moon phase transforms your fields. Raise strange livestock, befriend the night market and learn the old lunar calendar.', 'Mossline', 'Halfmoon Publishing', array['PC', 'Nintendo Switch 2', 'macOS']::text[], array['Simulation', 'Cozy']::text[], 'mock', '1020'),
  ('00000000-0000-4000-8000-000000000022', 'cinder-vault', 'Cinder Vault', null, 'A co-op heist roguelike inside a volcano bank.',
   'Plan a heist, then watch the plan fall apart. Cinder Vault is a four-player co-op roguelike about robbing a bank built inside an active volcano.', 'Concrete Garden', 'Concrete Garden', array['PC', 'PlayStation 5', 'Xbox Series X|S']::text[], array['Roguelite', 'Co-op', 'Multiplayer']::text[], 'mock', '1021')
